use std::fmt::Write as _;

use crate::model::{InterfaceBundle, MessageSpec};

pub fn render_grdr_strings(bundle: &InterfaceBundle) -> String {
    let mut out = String::new();
    out.push_str(
        "// @generated by grdr-interface-gen from contracts/interface/. Do not edit by hand.\n\n",
    );
    out.push_str("use serde::{Deserialize, Serialize};\n\n");

    out.push_str("/// Locale identifier supported by Guardrails desktop, CLI, and pseudo-locale CI checks (D-69).\n");
    out.push_str(
        "#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash, Serialize, Deserialize)]\n",
    );
    out.push_str("#[serde(rename_all = \"kebab-case\")]\n");
    out.push_str("pub enum Locale {\n");
    for (idx, loc) in bundle.locales.iter().enumerate() {
        if idx == 0 {
            out.push_str("    #[default]\n");
        }
        let _ = writeln!(out, "    {},", loc.rust_variant);
    }
    out.push_str("}\n\n");

    out.push_str(
        "/// Typed language-token identifiers used by desktop, CLI, tray, and `grdr-approve`.\n",
    );
    out.push_str("#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, Serialize, Deserialize)]\n");
    out.push_str("#[serde(rename_all = \"snake_case\")]\n");
    out.push_str("pub enum MessageKey {\n");
    let rust_messages = collect_rust_messages(bundle);
    for msg in &rust_messages {
        if let Some(variant) = &msg.rust_variant {
            let _ = writeln!(out, "    {variant},");
        }
    }
    out.push_str("}\n\n");

    out.push_str("#[derive(Clone, Copy, Debug, PartialEq, Eq)]\n");
    out.push_str("pub struct IconRegistryEntry {\n");
    out.push_str("    pub key: &'static str,\n");
    out.push_str("    pub lucide: &'static str,\n");
    out.push_str("    pub mirror: bool,\n");
    out.push_str("}\n\n");

    out.push_str("#[derive(Clone, Copy, Debug, PartialEq, Eq)]\n");
    out.push_str("pub struct PresentationRegistryEntry {\n");
    out.push_str("    pub enum_name: &'static str,\n");
    out.push_str("    pub value: &'static str,\n");
    out.push_str("    pub label_key: &'static str,\n");
    out.push_str("    pub description_key: Option<&'static str>,\n");
    out.push_str("    pub icon_key: &'static str,\n");
    out.push_str("    pub tone: &'static str,\n");
    out.push_str("}\n\n");

    let _ = writeln!(
        out,
        "pub const BRAND_NAME: &str = {};",
        rust_str(&bundle.vocabulary.brand_name)
    );
    let _ = writeln!(
        out,
        "pub const BRAND_SHORT_NAME: &str = {};\n",
        rust_str(&bundle.vocabulary.brand_short_name)
    );

    out.push_str("pub const ICONS: &[IconRegistryEntry] = &[\n");
    for icon in &bundle.icons {
        let _ = writeln!(out, "    IconRegistryEntry {{");
        let _ = writeln!(out, "        key: {},", rust_str(&icon.key));
        let _ = writeln!(out, "        lucide: {},", rust_str(&icon.lucide));
        let _ = writeln!(out, "        mirror: {},", icon.mirror);
        out.push_str("    },\n");
    }
    out.push_str("];\n\n");

    out.push_str("pub const PRESENTATIONS: &[PresentationRegistryEntry] = &[\n");
    for entry in &bundle.presentations {
        let desc = match &entry.description {
            Some(d) => format!("Some({})", rust_str(d)),
            None => "None".to_owned(),
        };
        out.push_str("    PresentationRegistryEntry {\n");
        let _ = writeln!(out, "        enum_name: {},", rust_str(&entry.enum_name));
        let _ = writeln!(out, "        value: {},", rust_str(&entry.value));
        let _ = writeln!(out, "        label_key: {},", rust_str(&entry.label));
        let _ = writeln!(out, "        description_key: {desc},");
        let _ = writeln!(out, "        icon_key: {},", rust_str(&entry.icon));
        let _ = writeln!(out, "        tone: {},", rust_str(&entry.tone));
        out.push_str("    },\n");
    }
    out.push_str("];\n\n");

    out.push_str("impl Locale {\n");
    out.push_str("    #[must_use]\n");
    out.push_str("    pub fn code(self) -> &'static str {\n");
    out.push_str("        match self {\n");
    for loc in &bundle.locales {
        let _ = writeln!(
            out,
            "            Self::{} => {},",
            loc.rust_variant,
            rust_str(&loc.tag)
        );
    }
    out.push_str("        }\n");
    out.push_str("    }\n\n");
    out.push_str("    #[must_use]\n");
    out.push_str("    pub fn direction(self) -> &'static str {\n");
    out.push_str("        match self {\n");
    for loc in &bundle.locales {
        let _ = writeln!(
            out,
            "            Self::{} => {},",
            loc.rust_variant,
            rust_str(&loc.direction)
        );
    }
    out.push_str("        }\n");
    out.push_str("    }\n\n");
    out.push_str("    #[must_use]\n");
    out.push_str("    pub fn parse_tag(raw: &str) -> Option<Self> {\n");
    out.push_str("        match raw.trim().to_ascii_lowercase().as_str() {\n");
    for loc in &bundle.locales {
        if loc.aliases.is_empty() {
            let _ = writeln!(
                out,
                "            {} => Some(Self::{}),",
                rust_str(&loc.tag.to_ascii_lowercase()),
                loc.rust_variant
            );
        } else {
            let pats: Vec<String> = loc.aliases.iter().map(|a| rust_str(a)).collect();
            let _ = writeln!(
                out,
                "            {} => Some(Self::{}),",
                pats.join(" | "),
                loc.rust_variant
            );
        }
    }
    out.push_str("            _ => None,\n");
    out.push_str("        }\n");
    out.push_str("    }\n");
    out.push_str("}\n\n");

    out.push_str("impl MessageKey {\n");
    out.push_str("    #[must_use]\n");
    out.push_str("    pub fn token_id(self) -> &'static str {\n");
    out.push_str("        match self {\n");
    for msg in &rust_messages {
        if let Some(variant) = &msg.rust_variant {
            let _ = writeln!(out, "            Self::{variant} => {},", rust_str(&msg.id));
        }
    }
    out.push_str("        }\n");
    out.push_str("    }\n\n");
    out.push_str("    #[must_use]\n");
    out.push_str("    pub fn english(self) -> &'static str {\n");
    out.push_str("        match self {\n");
    for msg in &rust_messages {
        if let Some(variant) = &msg.rust_variant {
            let _ = writeln!(
                out,
                "            Self::{variant} => {},",
                rust_str(&msg.msg)
            );
        }
    }
    out.push_str("        }\n");
    out.push_str("    }\n");
    out.push_str("}\n\n");

    out.push_str("/// Looks up any generated language token by string identifier.\n");
    out.push_str("#[must_use]\n");
    out.push_str("pub fn english_by_id(token_id: &str) -> Option<&'static str> {\n");
    out.push_str("    match token_id {\n");
    for msg in &bundle.messages {
        let key_lit = rust_str(&msg.id);
        let val_lit = rust_str(&msg.msg);
        let single_line = format!("        {key_lit} => Some({val_lit}),");
        if single_line.len() <= 100 {
            let _ = writeln!(out, "{single_line}");
        } else if format!("            Some({val_lit})").len() <= 100 {
            let _ = writeln!(out, "        {key_lit} => {{");
            let _ = writeln!(out, "            Some({val_lit})");
            out.push_str("        }\n");
        } else {
            let _ = writeln!(out, "        {key_lit} => Some(");
            let _ = writeln!(out, "            {val_lit},");
            out.push_str("        ),\n");
        }
    }
    out.push_str("        _ => None,\n");
    out.push_str("    }\n");
    out.push_str("}\n\n");

    out.push_str("/// Renders a language token cleanly for the requested locale.\n");
    out.push_str("#[must_use]\n");
    out.push_str("pub fn lookup(locale: Locale, key: MessageKey) -> String {\n");
    out.push_str("    format_for_locale(locale, key.english())\n");
    out.push_str("}\n\n");

    out.push_str("/// Formats an arbitrary base English string under the active locale.\n");
    out.push_str("#[must_use]\n");
    out.push_str("pub fn format_for_locale(locale: Locale, base: &str) -> String {\n");
    out.push_str("    match locale {\n");
    out.push_str("        Locale::EnUs => base.to_owned(),\n");
    out.push_str("        Locale::EnXa => format!(\"[{base} ~~~]\"),\n");
    out.push_str("        Locale::ArXb => format!(\"\\u{2066}{base}\\u{2069}\"),\n");
    out.push_str("        Locale::JaXc => format!(\"「{base}」\"),\n");
    out.push_str("    }\n");
    out.push_str("}\n");

    out
}

pub fn render_grdr_messages(bundle: &InterfaceBundle) -> String {
    let mut out = String::new();
    out.push_str(
        "// @generated by grdr-interface-gen from contracts/interface/. Do not edit by hand.\n\n",
    );
    out.push_str(
        "use grdr_strings::{Locale, PRESENTATIONS, english_by_id, format_for_locale};\n\n",
    );
    let _ = writeln!(
        out,
        "pub const GENERATED_BRAND_NAME: &str = {};\n",
        rust_str(&bundle.vocabulary.brand_name)
    );
    out.push_str("#[derive(Clone, Debug, PartialEq, Eq)]\n");
    out.push_str("pub struct PresentedValue {\n");
    out.push_str("    pub label: String,\n");
    out.push_str("    pub description: Option<String>,\n");
    out.push_str("    pub icon_key: &'static str,\n");
    out.push_str("    pub tone: &'static str,\n");
    out.push_str("}\n\n");

    out.push_str("/// Looks up a presentation-registry entry by enum name and serialized value.\n");
    out.push_str("#[must_use]\n");
    out.push_str("pub fn present_enum(enum_name: &str, value: &str, locale: Locale) -> Option<PresentedValue> {\n");
    out.push_str("    let entry = PRESENTATIONS\n");
    out.push_str("        .iter()\n");
    out.push_str("        .find(|item| item.enum_name == enum_name && item.value == value)?;\n");
    out.push_str("    let label_base = english_by_id(entry.label_key)?;\n");
    out.push_str("    let description = entry\n");
    out.push_str("        .description_key\n");
    out.push_str("        .and_then(english_by_id)\n");
    out.push_str("        .map(|base| format_for_locale(locale, base));\n");
    out.push_str("    Some(PresentedValue {\n");
    out.push_str("        label: format_for_locale(locale, label_base),\n");
    out.push_str("        description,\n");
    out.push_str("        icon_key: entry.icon_key,\n");
    out.push_str("        tone: entry.tone,\n");
    out.push_str("    })\n");
    out.push_str("}\n");

    out
}

fn collect_rust_messages(bundle: &InterfaceBundle) -> Vec<&MessageSpec> {
    let preferred_order = [
        "grdr.brand.name",
        "desktop.nav.first_run",
        "desktop.nav.home",
        "desktop.nav.activity",
        "desktop.nav.rules",
        "desktop.nav.privacy",
        "desktop.nav.settings",
        "desktop.status.protected",
        "desktop.status.requests_only",
        "desktop.status.scan_only",
        "desktop.approver.self",
        "desktop.approver.sponsor",
        "desktop.approver.admin",
        "desktop.approver.quorum",
        "desktop.why.blocked",
        "desktop.why.step_up",
        "desktop.why.modified",
        "desktop.why.delayed",
        "desktop.rules.widening_confirm",
        "desktop.privacy.disclosure",
        "desktop.render.web_fallback",
    ];
    let mut out = Vec::new();
    for id in preferred_order {
        if let Some(msg) = bundle
            .messages
            .iter()
            .find(|m| m.id == id && m.rust_variant.is_some())
        {
            out.push(msg);
        }
    }
    for msg in &bundle.messages {
        if msg.rust_variant.is_some() && !preferred_order.contains(&msg.id.as_str()) {
            out.push(msg);
        }
    }
    out
}

pub fn rust_str(value: &str) -> String {
    serde_json::to_string(value).unwrap_or_else(|_| "\"\"".to_owned())
}
